sys_script_include.script:
var CustomAjaxProcessor = Class.create();
CustomAjaxProcessor.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    updateField: function() {
        try {
            var recordSysId = this.getParameter('sysparm_record_sys_id');
            var newValue = this.getParameter('sysparm_new_value');
         //   var newValue = '更新于 ' + new GlideDateTime().getDisplayValue();
			if(newValue !== "") {
				return 'success';
			} else {
				return '错误: 记录未找到';
			}
            // var gr = new GlideRecord('your_table_name'); // 替换为你的表名
            // if (gr.get(recordSysId)) {
            //     gr.setValue('your_field_name', newValue); // 替换为你的字段名
            //     gr.update();
            //     return 'success';
            // } else {
            //     return '错误: 记录未找到';
            // }
        } catch (e) {
            return '错误: ' + e.message;
        }
    },
    type: 'CustomAjaxProcessor'
});
